// Local lexicon cards backed by open, attributable data.
//
// The packs in data/lexicon are generated by tools/build_lexicon.py:
//   ar-lane.tsv.gz   Lane's Arabic-English Lexicon, indexed by Arabic root
//   zh-cedict.tsv.gz CC-CEDICT, indexed by simplified and traditional word
//
// This is a reference layer, not a translation engine. It gives the reader the
// range of senses that a single-word translation often collapses.

using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace Qalam
{
    internal sealed class LexiconSense
    {
        public string Language;
        public string Headword;
        public string Alternate;
        public string Pronunciation;
        public string Root;
        public string PartOfSpeech;
        public string Era;
        public string Register;
        public string Gloss;
        public string Source;
    }

    internal sealed class LexiconInfo
    {
        public string Query;
        public string Language;
        public string Headword;
        public string Pronunciation;
        public string Root;
        public string Sources;
        public string Context;
        public List<LexiconSense> Senses = new List<LexiconSense>();

        public bool HasContent { get { return Senses.Count > 0; } }
    }

    internal sealed class LexiconService
    {
        private static readonly LexiconService _shared = new LexiconService();
        public static LexiconService Shared { get { return _shared; } }

        private readonly object _gate = new object();
        private readonly Dictionary<string, List<LexiconSense>> _words =
            new Dictionary<string, List<LexiconSense>>(StringComparer.Ordinal);
        private readonly Dictionary<string, List<LexiconSense>> _roots =
            new Dictionary<string, List<LexiconSense>>(StringComparer.Ordinal);
        private bool _loaded;
        private string _error = "";

        public string Error { get { EnsureLoaded(); return _error; } }
        public int Count { get { EnsureLoaded(); return _words.Count; } }

        public LexiconInfo Lookup(string text, string language, string context = null)
        {
            EnsureLoaded();

            LexiconInfo info = new LexiconInfo();
            info.Query = text;
            info.Context = CleanContext(context);
            string lang = NormalizeLanguage(language);
            if (lang == null) lang = DetectLanguage(text);
            if (lang == null) return info;
            info.Language = lang;

            string normalized = Normalize(text, lang);
            if (normalized.Length == 0) return info;

            List<string> candidates = lang == "ar"
                ? ArabicCandidates(normalized) : new List<string>(new string[] { normalized });
            List<LexiconSense> found = null;
            lock (_gate)
            {
                foreach (string candidate in candidates)
                {
                    string key = lang + "|" + candidate;
                    _words.TryGetValue(key, out found);
                    if ((found == null || found.Count == 0) && lang == "ar")
                        _roots.TryGetValue(key, out found);
                    if (found != null && found.Count > 0) break;
                    found = null;
                }
            }
            if (found == null || found.Count == 0) return info;

            // Preserve the source's sense order. Lane lists the primary
            // rendering first; an alphabetical sort would bury it behind
            // unrelated derived nouns. Only the era is grouped, modern first.
            List<LexiconSense> ordered = new List<LexiconSense>();
            for (int rank = 0; rank <= 3; rank++)
            {
                foreach (LexiconSense sense in found)
                    if (EraRank(sense.Era) == rank) ordered.Add(sense);
            }

            if (info.Context.Length > 0)
            {
                bool matched;
                ordered = RankByContext(ordered, ContextTerms(info.Context), out matched);
                if (!matched) info.Context = "";
            }

            HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (LexiconSense sense in ordered)
            {
                string identity = sense.Headword + "\u0001" + sense.Gloss;
                if (!seen.Add(identity)) continue;
                info.Senses.Add(sense);
                if (info.Senses.Count >= 8) break;
            }
            if (info.Senses.Count == 0) return info;

            LexiconSense first = info.Senses[0];
            info.Headword = first.Headword;
            info.Pronunciation = first.Pronunciation;
            info.Root = first.Root;

            List<string> sources = new List<string>();
            foreach (LexiconSense sense in info.Senses)
            {
                if (!string.IsNullOrEmpty(sense.Source) && !sources.Contains(sense.Source))
                    sources.Add(sense.Source);
            }
            info.Sources = string.Join("  \u00b7  ", sources.ToArray());
            return info;
        }

        private static string CleanContext(string context)
        {
            if (string.IsNullOrWhiteSpace(context)) return "";
            string value = context.Trim();
            if (value.Length > 80) value = value.Substring(0, 80).Trim();
            return value;
        }

        private static List<string> ContextTerms(string context)
        {
            List<string> terms = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            StringBuilder word = new StringBuilder();
            for (int i = 0; i <= context.Length; i++)
            {
                char c = i < context.Length ? context[i] : ' ';
                if (char.IsLetterOrDigit(c))
                {
                    word.Append(c);
                    continue;
                }
                if (word.Length >= 2)
                {
                    string term = word.ToString();
                    if (!ContextStopWords.Contains(term) && seen.Add(term)) terms.Add(term);
                }
                word.Length = 0;
                if (terms.Count >= 8) break;
            }
            return terms;
        }

        private static List<LexiconSense> RankByContext(List<LexiconSense> senses, List<string> terms, out bool matched)
        {
            matched = false;
            if (terms.Count == 0) return senses;

            int[] scores = new int[senses.Count];
            for (int i = 0; i < senses.Count; i++)
            {
                scores[i] = ContextScore(senses[i].Gloss, terms);
                if (scores[i] > 0) matched = true;
            }
            if (!matched) return senses;

            List<int> order = new List<int>();
            for (int i = 0; i < senses.Count; i++) order.Add(i);
            order.Sort(delegate(int a, int b)
            {
                int score = scores[b].CompareTo(scores[a]);
                return score != 0 ? score : a.CompareTo(b);
            });

            List<LexiconSense> ranked = new List<LexiconSense>(senses.Count);
            foreach (int index in order) ranked.Add(senses[index]);
            return ranked;
        }

        private static int ContextScore(string gloss, List<string> terms)
        {
            if (string.IsNullOrEmpty(gloss)) return 0;
            int score = 0;
            foreach (string term in terms)
            {
                if (ContainsWord(gloss, term)) score += 4;
                else if (gloss.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0) score += 1;
            }
            // Lane's "syn. with" rows are cross-references, not renderings;
            // keep them available but behind an actual contextual definition.
            if (score > 0 && gloss.TrimStart().StartsWith("syn.", StringComparison.OrdinalIgnoreCase))
                score--;
            return score;
        }

        private static bool ContainsWord(string text, string term)
        {
            int index = 0;
            while ((index = text.IndexOf(term, index, StringComparison.OrdinalIgnoreCase)) >= 0)
            {
                bool left = index == 0 || !char.IsLetterOrDigit(text[index - 1]);
                int end = index + term.Length;
                bool right = end >= text.Length || !char.IsLetterOrDigit(text[end]);
                if (left && right) return true;
                index += term.Length;
            }
            return false;
        }

        private static readonly HashSet<string> ContextStopWords = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "the", "a", "an", "to", "of", "and", "or", "in", "on", "for", "with",
            "is", "are", "was", "were", "be", "been", "being", "this", "that",
            "these", "those", "it", "its", "he", "she", "they", "them", "his",
            "her", "their", "as", "at", "by", "from", "not", "no", "but", "if",
            "then", "than", "so", "such", "one", "some", "any", "all", "very",
            "can", "could", "will", "would", "should", "may", "might", "do",
            "does", "did", "has", "have", "had", "here", "there", "when", "where",
            "who", "what", "which", "how", "why"
        };

        private static List<string> ArabicCandidates(string value)
        {
            List<string> candidates = new List<string>();
            AddCandidate(candidates, value);

            string bare = value;
            if (bare.StartsWith("\u0627\u0644", StringComparison.Ordinal) && bare.Length > 3)
            {
                bare = bare.Substring(2);
                AddCandidate(candidates, bare);
            }

            string[] prefixes = new string[]
            {
                "\u0627\u0633\u062a", "\u0623\u0633\u062a", "\u0648\u0627\u0644", "\u0628\u0627\u0644",
                "\u0643\u0627\u0644", "\u0641\u0627\u0644", "\u0644\u0644", "\u0648", "\u0641",
                "\u0628", "\u0643", "\u0644", "\u0645", "\u062a", "\u0646", "\u064a", "\u0633"
            };
            foreach (string prefix in prefixes)
            {
                if (!bare.StartsWith(prefix, StringComparison.Ordinal)) continue;
                string remainder = bare.Substring(prefix.Length);
                if (remainder.Length >= 3) AddCandidate(candidates, remainder);
            }

            // Weak letters and the feminine ending often sit between a derived
            // form and its root (كتاب -> كتب, مكتبة -> كتب). This is only a
            // fallback, and only for candidates long enough to be meaningful.
            int count = candidates.Count;
            for (int i = 0; i < count; i++)
            {
                string weak = RemoveWeakLetters(candidates[i]);
                if (weak.Length >= 3 && weak != candidates[i]) AddCandidate(candidates, weak);
            }
            return candidates;
        }

        private static void AddCandidate(List<string> candidates, string value)
        {
            if (string.IsNullOrEmpty(value) || candidates.Contains(value)) return;
            candidates.Add(value);
        }

        private static string RemoveWeakLetters(string value)
        {
            StringBuilder builder = new StringBuilder(value.Length);
            foreach (char c in value)
            {
                if (c == '\u0627' || c == '\u0648' || c == '\u064a' || c == '\u0649' ||
                    c == '\u0629' || c == '\u0647') continue;
                builder.Append(c);
            }
            return builder.ToString();
        }

        private static int EraRank(string era)
        {
            if (string.Equals(era, "modern", StringComparison.OrdinalIgnoreCase)) return 0;
            if (string.Equals(era, "classical", StringComparison.OrdinalIgnoreCase)) return 1;
            if (string.Equals(era, "quranic", StringComparison.OrdinalIgnoreCase)) return 2;
            return 3;
        }

        private static string NormalizeLanguage(string language)
        {
            if (string.IsNullOrEmpty(language)) return null;
            string value = language.Trim().ToLowerInvariant();
            if (value == "ar" || value.StartsWith("ar-", StringComparison.Ordinal)) return "ar";
            if (value == "zh" || value.StartsWith("zh-", StringComparison.Ordinal)) return "zh";
            return null;
        }

        private static string DetectLanguage(string text)
        {
            if (string.IsNullOrEmpty(text)) return null;
            if (ArabicText.ContainsArabic(text)) return "ar";
            if (ChineseText.ContainsHan(text)) return "zh";
            return null;
        }

        internal static string Normalize(string text, string language)
        {
            string value = (text ?? "").Trim();
            value = value.Trim(' ', '\t', '\r', '\n', '.', ',', ';', ':', '!', '?',
                '\u061f', '\u060c', '\u3002', '\uff0c', '\uff01', '\uff1f',
                '\u201c', '\u201d', '\'', '"');
            if (value.Length == 0) return "";

            if (language == "ar")
            {
                StringBuilder builder = new StringBuilder(value.Length);
                foreach (char c in value)
                {
                    if (ArabicText.IsMark(c) || c == '\u0640') continue;
                    char normalized = c;
                    if (c == '\u0623' || c == '\u0625' || c == '\u0622' || c == '\u0671') normalized = '\u0627';
                    else if (c == '\u0649') normalized = '\u064a';
                    else if (c == '\u0629') normalized = '\u0647';
                    else if (c == '\u0624') normalized = '\u0648';
                    else if (c == '\u0626') normalized = '\u064a';
                    else if (c == '\u0621') continue;
                    builder.Append(normalized);
                }
                value = builder.ToString();
            }
            else if (language == "zh")
            {
                value = value.Replace(" ", "").Replace("\t", "");
            }
            return value.ToLowerInvariant();
        }

        private void EnsureLoaded()
        {
            lock (_gate)
            {
                if (_loaded) return;
                _loaded = true;
                int rows = 0;
                int files = 0;
                foreach (string path in FindDataFiles())
                {
                    try
                    {
                        rows += LoadFile(path);
                        files++;
                    }
                    catch (Exception ex)
                    {
                        Logger.Write("lexicon " + Path.GetFileName(path) + ": " + ex.Message);
                    }
                }
                if (files == 0)
                {
                    _error = "Lexicon data not found. Run tools/build_lexicon.py and reinstall.";
                    Logger.Write("lexicon: " + _error);
                }
                else
                {
                    Logger.Write("lexicon loaded: " + rows + " rows from " + files + " file(s)");
                }
            }
        }

        private static List<string> FindDataFiles()
        {
            List<string> directories = new List<string>();
            directories.Add(Path.Combine(Paths.AppDir, "data", "lexicon"));
            DirectoryInfo parent = Directory.GetParent(Paths.AppDir);
            if (parent != null) directories.Add(Path.Combine(parent.FullName, "data", "lexicon"));
            directories.Add(Path.Combine(Paths.DataDir, "lexicon"));

            List<string> files = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string directory in directories)
            {
                try
                {
                    if (!Directory.Exists(directory)) continue;
                    List<string> candidates = new List<string>();
                    candidates.AddRange(Directory.GetFiles(directory, "*.tsv.gz"));
                    candidates.AddRange(Directory.GetFiles(directory, "*.tsv"));
                    candidates.Sort(StringComparer.OrdinalIgnoreCase);
                    foreach (string candidate in candidates)
                    {
                        string name = Path.GetFileName(candidate);
                        if (seen.Add(name)) files.Add(candidate);
                    }
                }
                catch (Exception ex)
                {
                    Logger.Write("lexicon directory " + directory + ": " + ex.Message);
                }
            }
            return files;
        }

        private int LoadFile(string path)
        {
            int rows = 0;
            using (FileStream file = File.OpenRead(path))
            using (Stream stream = path.EndsWith(".gz", StringComparison.OrdinalIgnoreCase)
                ? (Stream)new GZipStream(file, CompressionMode.Decompress) : file)
            using (StreamReader reader = new StreamReader(stream, Encoding.UTF8, true))
            {
                string line = reader.ReadLine();
                if (line == null) return 0;
                bool header = line.StartsWith("lang\t", StringComparison.OrdinalIgnoreCase);
                while (line != null)
                {
                    if (!header)
                    {
                        LexiconSense sense = ParseLine(line);
                        if (sense != null) { Index(sense); rows++; }
                    }
                    header = false;
                    line = reader.ReadLine();
                }
            }
            return rows;
        }

        private static LexiconSense ParseLine(string line)
        {
            if (string.IsNullOrEmpty(line)) return null;
            string[] parts = line.Split('\t');
            if (parts.Length < 10) return null;
            string language = (parts[0] ?? "").Trim().ToLowerInvariant();
            if (language != "ar" && language != "zh") return null;
            if (string.IsNullOrWhiteSpace(parts[1]) || string.IsNullOrWhiteSpace(parts[8])) return null;

            LexiconSense sense = new LexiconSense();
            sense.Language = language;
            sense.Headword = parts[1].Trim();
            sense.Alternate = parts[2].Trim();
            sense.Pronunciation = parts[3].Trim();
            sense.Root = parts[4].Trim();
            sense.PartOfSpeech = parts[5].Trim();
            sense.Era = parts[6].Trim();
            sense.Register = parts[7].Trim();
            sense.Gloss = parts[8].Trim();
            sense.Source = parts[9].Trim();
            return sense;
        }

        private void Index(LexiconSense sense)
        {
            AddIndex(_words, sense.Language, sense.Headword, sense);
            AddIndex(_words, sense.Language, sense.Alternate, sense);
            AddIndex(_roots, sense.Language, sense.Root, sense);
        }

        private static void AddIndex(Dictionary<string, List<LexiconSense>> index,
            string language, string value, LexiconSense sense)
        {
            if (string.IsNullOrEmpty(value)) return;
            string normalized = Normalize(value, language);
            if (normalized.Length == 0) return;
            string key = language + "|" + normalized;
            List<LexiconSense> list;
            if (!index.TryGetValue(key, out list))
            {
                list = new List<LexiconSense>();
                index[key] = list;
            }
            list.Add(sense);
        }
    }

    internal static class LexiconText
    {
        public static string Title(LexiconInfo info)
        {
            if (info == null) return "SENSES";
            string title = "SENSES  \u00b7  " + (info.Language == "ar" ? "ARABIC" : "CHINESE");
            if (!string.IsNullOrEmpty(info.Root))
                title += "  \u00b7  ROOT " + info.Root;
            else if (!string.IsNullOrEmpty(info.Pronunciation))
                title += "  \u00b7  " + info.Pronunciation;
            return title;
        }

        public static string Summary(LexiconInfo info)
        {
            if (info == null || info.Senses.Count == 0) return "";
            StringBuilder text = new StringBuilder();
            foreach (LexiconSense sense in info.Senses)
            {
                if (text.Length > 0) text.Append('\n');
                text.Append('\u2022').Append(' ');
                if (!string.IsNullOrEmpty(sense.Era))
                    text.Append('[').Append(UpperFirst(sense.Era)).Append("] ");
                text.Append(sense.Gloss);
            }
            return text.ToString();
        }

        private static string UpperFirst(string value)
        {
            if (string.IsNullOrEmpty(value)) return value;
            return char.ToUpperInvariant(value[0]) + value.Substring(1);
        }
    }

    internal static class LexiconSelfTest
    {
        public static int RunUi(string[] args)
        {
            string output = Path.Combine(Paths.AppDir, "selftest", "lexicon");
            for (int i = 0; i + 1 < args.Length; i++)
                if (string.Equals(args[i], "--out", StringComparison.OrdinalIgnoreCase))
                    output = Path.GetFullPath(args[i + 1]);
            Directory.CreateDirectory(output);

            StringBuilder log = new StringBuilder();
            int exit = 0;
            try
            {
                Application application = new Application();
                application.ShutdownMode = ShutdownMode.OnExplicitShutdown;

                Config config = new Config();
                TranslationService translator = new TranslationService();
                TashkeelClient tashkeel = new TashkeelClient(config);
                GrammarService grammar = new GrammarService();

                exit |= RenderCase(application, config, translator, tashkeel, grammar,
                    "\u0643\u062a\u0628", "ar", "ROOT", "wrote", "wrote",
                    Path.Combine(output, "lexicon-ar.png"), log, false);
                exit |= RenderCase(application, config, translator, tashkeel, grammar,
                    "\u5b66\u751f", "zh", "CHINESE", "student", "student",
                    Path.Combine(output, "lexicon-zh.png"), log, false);
                exit |= RenderCase(application, config, translator, tashkeel, grammar,
                    "\u0643\u062a\u0627\u0628", "ar", "ROOT", "book", "book",
                    Path.Combine(output, "lexicon-popup-ar.png"), log, true);

                application.Shutdown();
            }
            catch (Exception ex)
            {
                exit = 1;
                log.AppendLine("UI_FAIL=" + ex);
            }

            File.WriteAllText(Path.Combine(output, "lexicon-ui.txt"), log.ToString(), Utf8.NoBom);
            Console.WriteLine(log.ToString());
            return exit;
        }

        private static int RenderCase(Application application, Config config,
            TranslationService translator, TashkeelClient tashkeel, GrammarService grammar,
            string word, string language, string expectedTitle, string expectedGloss,
            string context, string imagePath, StringBuilder log, bool fromPopup)
        {
            MainWindow window = new MainWindow(config, translator, tashkeel, grammar, null, null);
            window.WindowStartupLocation = WindowStartupLocation.Manual;
            window.Left = -32000;
            window.Top = -32000;
            window.Width = 760;
            window.Height = 900;
            window.ShowInTaskbar = false;
            window.ShowActivated = false;
            window.Show();
            window.UpdateLayout();

            BindingFlags flags = BindingFlags.Instance | BindingFlags.NonPublic;
            if (fromPopup)
            {
                TranslationResult result = new TranslationResult();
                result.SourceText = word;
                result.Translation = context;
                result.Detected = language;
                result.Target = "en";
                result.MaxChars = 10000;
                window.ShowFromPopup(result);
            }
            else
            {
                MethodInfo show = typeof(MainWindow).GetMethod("ShowLexicon", flags);
                if (show == null) throw new InvalidOperationException("ShowLexicon not found.");
                show.Invoke(window, new object[] { word, language, context });
            }
            window.UpdateLayout();

            Border card = (Border)typeof(MainWindow).GetField("_lexiconCard", flags).GetValue(window);
            TextBlock title = (TextBlock)typeof(MainWindow).GetField("_lexiconTitle", flags).GetValue(window);
            TextBlock text = (TextBlock)typeof(MainWindow).GetField("_lexiconText", flags).GetValue(window);
            TextBlock credit = (TextBlock)typeof(MainWindow).GetField("_lexiconCredit", flags).GetValue(window);

            bool visible = card != null && card.Visibility == Visibility.Visible;
            bool titleOk = title != null && title.Text.IndexOf(expectedTitle, StringComparison.OrdinalIgnoreCase) >= 0;
            string firstLine = text == null ? "" : text.Text.Split('\n')[0];
            bool glossOk = firstLine.IndexOf(expectedGloss, StringComparison.OrdinalIgnoreCase) >= 0;
            bool contextOk = string.IsNullOrEmpty(context) ||
                (credit != null && credit.Text.IndexOf("Ranked for", StringComparison.OrdinalIgnoreCase) >= 0);
            if (!visible || !titleOk || !glossOk || !contextOk) return 1;

            RenderTargetBitmap bitmap = new RenderTargetBitmap(
                Math.Max(1, (int)Math.Ceiling(window.ActualWidth)),
                Math.Max(1, (int)Math.Ceiling(window.ActualHeight)),
                96, 96, PixelFormats.Pbgra32);
            bitmap.Render(window);
            PngBitmapEncoder encoder = new PngBitmapEncoder();
            encoder.Frames.Add(BitmapFrame.Create(bitmap));
            using (FileStream file = File.Create(imagePath)) encoder.Save(file);

            log.AppendLine(word + " [" + language + "] visible=" + visible +
                           " title=" + (title == null ? "" : title.Text) +
                           " context=" + context +
                           " first=" + firstLine +
                           " credit=" + (credit == null ? "" : credit.Text) +
                           " image=" + imagePath);
            window.AllowClose();
            window.Close();
            return 0;
        }

        public static int Run(string[] args)
        {
            string output = Path.Combine(Paths.AppDir, "lexicontest.txt");
            for (int i = 0; i + 1 < args.Length; i++)
                if (string.Equals(args[i], "--out", StringComparison.OrdinalIgnoreCase))
                    output = Path.GetFullPath(args[i + 1]);

            StringBuilder log = new StringBuilder();
            int exit = 0;
            LexiconService service = new LexiconService();
            log.AppendLine("count=" + service.Count);
            log.AppendLine("error=" + service.Error);
            if (service.Count < 1000)
            {
                log.AppendLine("FAIL: lexicon packs did not load");
                exit = 1;
            }

            Check(service, log, ref exit, "\u0643\u062a\u0628", "ar", "wrote", "Lane");
            Check(service, log, ref exit, "\u0643\u064e\u062a\u064e\u0628\u064e", "ar", "wrote", "Lane");
            CheckRoot(service, log, ref exit, "\u0643\u062a\u0627\u0628", "ar", "\u0643\u062a\u0628");
            CheckRoot(service, log, ref exit, "\u0627\u0633\u062a\u0643\u062a\u0628", "ar", "\u0643\u062a\u0628");
            CheckFirst(service, log, ref exit, "\u0643\u062a\u0627\u0628", "ar", "book", "book");
            CheckFirst(service, log, ref exit, "\u0643\u062a\u0628", "ar", "wrote", "wrote");
            CheckFirst(service, log, ref exit, "\u5b66\u751f", "zh", "student", "student");
            Check(service, log, ref exit, "\u5b66\u751f", "zh", "student", "CC-CEDICT");
            Check(service, log, ref exit, "\u5b78\u751f", "zh", "student", "CC-CEDICT");

            LexiconInfo none = service.Lookup("zzzz", "en");
            log.AppendLine("unknown_has_content=" + (none != null && none.HasContent));
            if (none != null && none.HasContent) exit = 1;

            string directory = Path.GetDirectoryName(Path.GetFullPath(output));
            if (!string.IsNullOrEmpty(directory)) Directory.CreateDirectory(directory);
            File.WriteAllText(output, log.ToString(), Utf8.NoBom);
            Console.WriteLine(log.ToString());
            return exit;
        }

        private static void CheckFirst(LexiconService service, StringBuilder log, ref int exit,
            string word, string language, string context, string expectedGloss)
        {
            LexiconInfo info = service.Lookup(word, language, context);
            bool ok = info != null && info.HasContent && info.Context.Length > 0 &&
                info.Senses[0].Gloss.IndexOf(expectedGloss, StringComparison.OrdinalIgnoreCase) >= 0;
            if (!ok) exit = 1;
            string first = info == null || info.Senses.Count == 0 ? "" : info.Senses[0].Gloss;
            log.AppendLine(word + " [context=" + context + "] first=" + first +
                           " ok=" + ok);
        }

        private static void CheckRoot(LexiconService service, StringBuilder log, ref int exit,
            string word, string language, string expectedRoot)
        {
            LexiconInfo info = service.Lookup(word, language);
            bool ok = info != null && info.HasContent && info.Root == expectedRoot;
            if (!ok) exit = 1;
            log.AppendLine(word + " [" + language + "] root=" + (info == null ? "" : info.Root) +
                           " expected=" + expectedRoot + " ok=" + ok);
        }

        private static void Check(LexiconService service, StringBuilder log, ref int exit,
            string word, string language, string expectedGloss, string expectedSource)
        {
            LexiconInfo info = service.Lookup(word, language);
            bool ok = info != null && info.HasContent;
            bool gloss = false;
            bool source = false;
            if (ok)
            {
                foreach (LexiconSense sense in info.Senses)
                {
                    if (sense.Gloss.IndexOf(expectedGloss, StringComparison.OrdinalIgnoreCase) >= 0) gloss = true;
                    if (sense.Source.IndexOf(expectedSource, StringComparison.OrdinalIgnoreCase) >= 0) source = true;
                }
            }
            if (!ok || !gloss || !source) exit = 1;
            log.AppendLine(word + " [" + language + "] ok=" + ok + " gloss=" + gloss +
                           " source=" + source + " senses=" + (info == null ? 0 : info.Senses.Count));
            if (ok)
            {
                foreach (LexiconSense sense in info.Senses)
                    log.AppendLine("  " + sense.Gloss + "  (" + sense.Source + ")");
            }
        }
    }
}
